UPDATE rrs_securityinfo
SET full_name = #{securityName}
   ,short_name = #{securityName}
   ,security_type = #{securityType}
   ,issuer = #{tempCompanyNameSnapshot}
   ,firstissue_date = DATE_FORMAT(#{tempIssueDate}, '%Y%m%d')
   ,maturity_date = DATE_FORMAT(#{tempMaturityDate}, '%Y%m%d')
   ,ts = #{updateTime}
WHERE wind_code = #{securityCode}

UPDATE rrs_securityinfo
SET maturity_date = #{cancelDate}
   ,end_date = #{cancelDate}
   ,security_status = 'D'
   ,ts = #{updateTime}
WHERE wind_code = #{tempSecurityCode}

UPDATE rrs_securityinfo
SET security_status = 'D'
   ,ts = #{updateTime}
WHERE wind_code = #{tempSecurityCode}
  AND security_source = 'temporary'

UPDATE rrs_temp_security_code
SET temp_security_name = #{bo.tempSecurityName}
   ,temp_security_code = #{bo.tempSecurityCode}
   ,temp_security_market = #{bo.tempSecurityMarket}
   ,temp_security_type = #{bo.tempSecurityType}
   ,temp_mitigation_code = #{bo.tempMitigationCode}
   ,temp_company_code = #{bo.tempCompanyCode}
   ,temp_company_name_snapshot = #{bo.tempCompanyNameSnapshot}
   ,temp_issue_date = #{bo.tempIssueDate}
   ,temp_maturity_date = #{bo.tempMaturityDate}
   ,security_name = #{bo.securityName}
   ,security_code = #{bo.securityCode}
   ,security_market = #{bo.securityMarket}
   ,security_type = #{bo.securityType}
   ,update_time = #{bo.updateTime}
   ,status = #{bo.status}
   ,oprt_source = #{bo.oprtSource}
   ,memo = #{bo.memo}
   ,updt_time = #{bo.updtTime}
WHERE id = #{bo.id}
  AND is_deleted = 0
  AND status = 'temporary'

UPDATE rrs_temp_security_code
SET update_time = #{updateTime}
   ,status = #{status}
   ,oprt_source = #{oprtSource}
   ,updt_time = #{updtTime}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE rrs_temp_security_code
