mapper.select:
SELECT SUM(ref_count) AS refCount
FROM (
    SELECT COUNT(1) AS ref_count
    FROM ip_adjust_log
    WHERE is_deleted = 0
      AND security_code = #{tempSecurityCode}
      AND security_type = #{tempSecurityType}
    UNION ALL
    SELECT COUNT(1) AS ref_count
    FROM ip_pool_status
    WHERE is_deleted = 0
      AND security_code = #{tempSecurityCode}
      AND security_type = #{tempSecurityType}
    UNION ALL
    SELECT COUNT(1) AS ref_count
    FROM ip_adjust_log
    WHERE is_deleted = 0
      AND crmw_scode = #{tempSecurityCode}
      AND crmw_stype = #{tempSecurityType}
      AND crmw_mktcode = #{tempSecurityMarket}
    UNION ALL
    SELECT COUNT(1) AS ref_count
    FROM ip_pool_status
    WHERE is_deleted = 0
      AND crmw_scode = #{tempSecurityCode}
      AND crmw_stype = #{tempSecurityType}
      AND crmw_mktcode = #{tempSecurityMarket}
    UNION ALL
    SELECT COUNT(1) AS ref_count
    FROM ip_pool_status_crmw
    WHERE is_deleted = 0
      AND security_code = #{tempSecurityCode}
      AND security_type = #{tempSecurityType}
    UNION ALL
    SELECT COUNT(1) AS ref_count
    FROM ip_pool_status_crmw
    WHERE is_deleted = 0
      AND crmw_scode = #{tempSecurityCode}
      AND crmw_stype = #{tempSecurityType}
      AND crmw_mktcode = #{tempSecurityMarket}
) refs

